import{_ as d,c as o,o as e,b0 as a}from"./chunks/framework.C5ev1SXp.js";const r="/scm-docs/assets/ext-sram-framework.B55Cw_ny.svg",c="/scm-docs/assets/ext-sram-load-flow.Dw5l59_f.svg",S=JSON.parse('{"title":"LV065-外部SRAM-APP方案分析","description":null,"frontmatter":{"title":"LV065-外部SRAM-APP方案分析","date":"2026-10-17T19:31:30.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/online-upgrade/iap/126d62bb8aaa26154ad6ec19","index":true,"tags":null,"categories":["在线升级"],"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-10-17T19:31:30.609Z","fulluuid":"54ad6ec191844e6c90377ae2866c3058","useduuid":"54ad6ec19"}},"headers":[],"relativePath":"sdoc/online-upgrade/iap/126d62bb8aaa26154ad6ec19.md","filePath":"sdoc/70-在线升级/01-IAP/LV065-外部SRAM-APP方案分析.md","lastUpdated":1792242412000}'),s={name:"sdoc/online-upgrade/iap/126d62bb8aaa26154ad6ec19.md"};function l(h,t,n,p,i,P){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="lv065-外部sram-app方案分析" tabindex="-1">LV065-外部SRAM-APP方案分析 <a class="header-anchor" href="#lv065-外部sram-app方案分析" aria-label="Permalink to &quot;LV065-外部SRAM-APP方案分析&quot;">​</a></h1><h2 id="一、-方案背景与可行性" tabindex="-1">一、 方案背景与可行性 <a class="header-anchor" href="#一、-方案背景与可行性" aria-label="Permalink to &quot;一、 方案背景与可行性&quot;">​</a></h2><h3 id="_1-背景与动机" tabindex="-1">1. 背景与动机 <a class="header-anchor" href="#_1-背景与动机" aria-label="Permalink to &quot;1. 背景与动机&quot;">​</a></h3><p><a href="/scm-docs/sdoc/online-upgrade/iap/126b0f2764e7a002b543b.html">LV035-SRAM-APP设计</a> 把 APP 装进内部 SRAM 运行，容器固定 24KB——<code>.text</code> 一旦超过这个数，链接阶段就报 region 溢出。而这块板（STM32F103ZET6 + IS62WV51216）通过 FSMC 扩展了 1MB 外部 SRAM（NE3，基址 <code>0x68000000</code>），见 <a href="/scm-docs/sdoc/peripheral/fsmc/sram/126b0924b2d20263b97733d0.html">LV015-外部SRAM读写实例</a>。一个自然的想法是：把 APP 的运行容器从内部 SRAM 的 <code>0x20007000</code> 换到外部 SRAM 的 <code>0x68000000</code>，代码体积上限直接从 24KB 提到接近 1MB。</p><p>本文分析这个方案在机制上是否成立、需要哪些改动、以及放到这块板的具体资源格局下会付出什么代价。结论先行：<strong>机制成立，但板级代价不小，是否采用取决于性能实测与分区取舍</strong>。</p><h3 id="_2-取指可行性原理" tabindex="-1">2. 取指可行性原理 <a class="header-anchor" href="#_2-取指可行性原理" aria-label="Permalink to &quot;2. 取指可行性原理&quot;">​</a></h3><p>Cortex-M3 的取指只看地址落在哪个总线区域，不挑介质。ARMv7-M 默认内存映射中，<code>0x60000000</code> ~ <code>0x9FFFFFFF</code> 是&quot;外部 RAM&quot;Normal 存储区，<strong>不是 XN（Execute Never）区</strong>，允许取指。FSMC 把 IS62WV51216 映射到 <code>0x68000000</code> 后，它就是一块可随机访问的普通存储器，与内部 SRAM 的 <code>0x20000000</code> 在取指视角下没有本质区别。真正禁止取指的是 <code>0x40000000</code> ~ <code>0x5FFFFFFF</code> 外设区与 <code>0xE0000000</code> 起的系统区，FSMC 映射区不在其列。</p><p>与 LV035 相同的三个执行条件，一条都不能少：</p><p>（1）链接时的执行地址就是实际装载地址——位置相关代码，Bootloader 必须把镜像拷到链接器编址的那个位置；</p><p>（2）镜像的向量表在运行时被 <code>SCB-&gt;VTOR</code> 指向，中断才能找到处理函数——<code>0x68000000</code> 满足 VTOR 的 128 字节对齐要求；</p><p>（3）装载完成后按向量表把 MSP 换成镜像自己的栈顶。</p><h3 id="_3-与内部-sram-app-的同构性" tabindex="-1">3. 与内部 SRAM-APP 的同构性 <a class="header-anchor" href="#_3-与内部-sram-app-的同构性" aria-label="Permalink to &quot;3. 与内部 SRAM-APP 的同构性&quot;">​</a></h3><p>跳转机制一行都不用改：<code>iap_load_app()</code> 读目标处向量表、设 VTOR、<code>__set_MSP()</code>、跳 <code>Reset_Handler</code>（详见 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0ff7b4fb48fdf0eff.html">LV050-IAP跳转与向量表原理</a>）。差异只在两处：地址从 <code>0x20007000</code> 换成 <code>0x68000000</code>；新增一条&quot;FSMC 必须已初始化&quot;的启动依赖。</p><table tabindex="0"><thead><tr><th>维度</th><th>内部 SRAM-APP</th><th>外部 SRAM-APP</th></tr></thead><tbody><tr><td>运行位置</td><td><code>0x20007000</code></td><td><code>0x68000000</code></td></tr><tr><td>容器大小</td><td>24KB（内部 SRAM 分区限制）</td><td>最高接近 1MB（实际受暂存区约束，见四、1）</td></tr><tr><td>取指路径</td><td>I-bus / D-bus</td><td>System 总线 + FSMC</td></tr><tr><td>启动依赖</td><td>无（SRAM 上电即可用）</td><td>FSMC 已初始化、时钟一致</td></tr><tr><td>执行速度</td><td>与 Flash 无异</td><td>慢数倍（FSMC 等待周期，见四、3）</td></tr><tr><td>掉电行为</td><td>丢失，重新 <code>go sram</code></td><td>丢失，重新 <code>go sram</code></td></tr></tbody></table><h2 id="二、-整体框架与装载流程" tabindex="-1">二、 整体框架与装载流程 <a class="header-anchor" href="#二、-整体框架与装载流程" aria-label="Permalink to &quot;二、 整体框架与装载流程&quot;">​</a></h2><h3 id="_1-硬件框架与地址分区" tabindex="-1">1. 硬件框架与地址分区 <a class="header-anchor" href="#_1-硬件框架与地址分区" aria-label="Permalink to &quot;1. 硬件框架与地址分区&quot;">​</a></h3><p>图一是整个方案的硬件框架：Bootloader 在内部 FLASH 里经 ICode/DCode 总线执行；装载命令 <code>go sram</code> 把暂存区镜像经 System 总线、FSMC 搬到 NE3 的外部 SRAM；跳转后 APP 的每条指令都经同一条链路取回。</p><p><img src="'+r+'" alt="外部 SRAM-APP 的硬件框架与装载路径"></p><p>对应的地址分区建议：</p><table tabindex="0"><thead><tr><th>区域</th><th>地址</th><th>用途</th></tr></thead><tbody><tr><td>Bootloader</td><td><code>0x08000000</code> ~ <code>0x08020000</code>（128KB）</td><td>上电入口，负责 FSMC 初始化与装载</td></tr><tr><td>flash-app</td><td><code>0x08020000</code> ~ <code>0x08040000</code>（128KB）</td><td>主线交付镜像，不动</td></tr><tr><td>暂存区</td><td><code>0x08040000</code> ~ <code>0x08080000</code>（256KB）</td><td><code>app.img</code> 落盘位置，掉电保留</td></tr><tr><td>APP 数据区</td><td><code>0x2000D000</code> 起的内部 SRAM</td><td><code>.data</code>/<code>.bss</code>/堆/栈，保持内部 SRAM 的访问速度</td></tr><tr><td>代码容器</td><td><code>0x68000000</code> 起（≤256KB）</td><td>镜像装载与执行位置</td></tr><tr><td>剩余外部 SRAM</td><td>容器之后到 1MB</td><td>既有大缓冲区迁移至此（见四、2）</td></tr></tbody></table><p>分区设计的关键取舍：<strong>代码容器放外部 SRAM，RW 数据区继续留在内部 SRAM</strong>。这样 <code>.data</code>/<code>.bss</code>/堆/栈的访问速度不变、FSMC 流量最小，1MB 外存全部让给代码；栈溢出时也会先撞到 NOINIT 区而不是覆盖指令，沿用 LV035 的边界设计思想。</p><h3 id="_2-装载与启动流程" tabindex="-1">2. 装载与启动流程 <a class="header-anchor" href="#_2-装载与启动流程" aria-label="Permalink to &quot;2. 装载与启动流程&quot;">​</a></h3><p>图二按时间顺序给出从复位到业务运行的完整链路，Bootloader 侧六步、APP 侧两步，任何一环校验失败都留在 Bootloader 等待重发。</p><p><img src="'+c+'" alt="外部 SRAM-APP 的装载与启动流程"></p><p>与 LV035 的装载流程相比，有三处实质差异：</p><p>（1）<strong>装载前新增 FSMC 初始化</strong>。Bootloader 要往 <code>0x68000000</code> 写数据，FSMC 必须先配好——这是外部 SRAM 方案独有的、绕不开的前置步骤；</p><p>（2）<strong>搬运长度从&quot;固定容器大小&quot;改为&quot;帧头实际长度&quot;</strong>。LV035 固定搬满 24KB 容器是因为代价小；外部 SRAM 容器接近 1MB，整容器搬运每次 <code>go sram</code> 都要白搬几十万字节 <code>0xFF</code>，必须改为按帧头记录的实际长度搬运；</p><p>（3）<strong>向量表判据范围更新</strong>。栈顶判据仍是&quot;落在内部 SRAM&quot;，但复位向量判据从 <code>0x20007000 ~ 0x2000D000</code> 改为&quot;落在 <code>0x68000000</code> 起的容器内且最低位为 1&quot;。</p><p>APP 侧的启动顺序沿用 LV035 的约束：<code>main()</code> 里 <code>SCB-&gt;VTOR = APP_BASE</code> 必须早于 <code>HAL_Init()</code>，否则 SysTick 中断仍会按 Bootloader 的向量表跳进旧代码。</p><h3 id="_3-地址同步点" tabindex="-1">3. 地址同步点 <a class="header-anchor" href="#_3-地址同步点" aria-label="Permalink to &quot;3. 地址同步点&quot;">​</a></h3><p>沿用 LV035&quot;三处必须同步&quot;的方法论，同步点从三处扩到五处：</p><table tabindex="0"><thead><tr><th>位置</th><th>内容</th><th>不同步的后果</th></tr></thead><tbody><tr><td><code>sram-app.uvprojx</code> 的 IROM1</td><td><code>0x68000000</code> / 实际容量</td><td>镜像按错误地址编址，装载后跑飞</td></tr><tr><td><code>iap.h</code> 的 <code>IAP_SRAM_APP_BASE/MAX_SIZE</code></td><td>同上</td><td>帧头地址校验拒绝，或搬运越界</td></tr><tr><td><code>pack_iap.py</code> 的 <code>SRAM_APP_BASE/END</code></td><td>同上</td><td>打包时报 <code>address or size out of range</code></td></tr><tr><td><code>iap_load_app()</code> 向量表判据</td><td>外部 SRAM 地址范围</td><td>合法镜像被拒或非法数据被放行</td></tr><tr><td>外部 SRAM 内部再分区</td><td>容器起点、缓冲区起点</td><td>代码容器与既有缓冲区互相覆盖（见四、2）</td></tr></tbody></table><h2 id="三、-启动契约-fsmc-初始化与跳转" tabindex="-1">三、 启动契约：FSMC 初始化与跳转 <a class="header-anchor" href="#三、-启动契约-fsmc-初始化与跳转" aria-label="Permalink to &quot;三、 启动契约：FSMC 初始化与跳转&quot;">​</a></h2><p>这一节回答两个最容易被问到的疑问：<strong>跳转后 FSMC 相关寄存器会不会出问题？APP 还需不需要再初始化一次外部 SRAM？</strong></p><h3 id="_1-跳转不会破坏-fsmc-寄存器" tabindex="-1">1. 跳转不会破坏 FSMC 寄存器 <a class="header-anchor" href="#_1-跳转不会破坏-fsmc-寄存器" aria-label="Permalink to &quot;1. 跳转不会破坏 FSMC 寄存器&quot;">​</a></h3><p>跳转是&quot;硬跳&quot;：Bootloader 只改 PC、MSP、VTOR 三个东西，不碰任何外设寄存器。FSMC 的 GPIO 复用、<code>FSMC_BCRx</code>/<code>FSMC_BTRx</code> 配置<strong>原样移交给 APP</strong>。所以&quot;跳转这个动作会不会弄坏 FSMC&quot;的答案是：不会，寄存器值一位都不会变。</p><p>但要立刻补一句：APP 从第一条指令起就依赖这份配置——<code>Reset_Handler</code>、<code>SystemInit</code>、<code>__main</code> 的 scatterload 全部从 <code>0x68000000</code> 取指。这是外部 SRAM 执行与内部 SRAM 执行最本质的差别：内部 SRAM-APP 跳转后对外设零依赖，外部 SRAM-APP 把&quot;FSMC 已配置&quot;变成了隐形的启动契约。</p><h3 id="_2-app-是否需要重新初始化" tabindex="-1">2. APP 是否需要重新初始化 <a class="header-anchor" href="#_2-app-是否需要重新初始化" aria-label="Permalink to &quot;2. APP 是否需要重新初始化&quot;">​</a></h3><p>分三层看：</p><p>（1）<strong>APP 没有&quot;运行前自己初始化&quot;的机会</strong>。第一条指令就在外部 SRAM 里执行，此时 FSMC 必须已经工作——鸡生蛋问题，初始化权天然在 Bootloader 手里；</p><p>（2）<strong><code>main()</code> 里用相同参数再跑一次 <code>FSMC_Init</code> 是可以且无害的</strong>。相同值写回去不改变时序，不影响正在进行的取指，属于防御性编程，建议保留；</p><p>（3）<strong>APP 修改 FSMC 时序参数是禁止项</strong>。APP 正在外存里执行，改错的瞬间后续取指就是垃圾数据，直接 HardFault，没有第二次机会。</p><p>标准库也佐证了这个契约：<code>SystemInit()</code> 里预留了 <code>DATA_IN_ExtSRAM</code> 宏，定义后会调用 <code>SystemInit_ExtMemCtl()</code> 初始化 FSMC——官方对&quot;代码在外存执行&quot;的标准做法就是启动最早期初始化外存。IAP 场景下这份职责前移到了 Bootloader，但&quot;谁让代码落进外存，谁负责先配好 FSMC&quot;的契约不变。APP 对其余外设为何必须全量重配、FSMC 为何是唯一例外，一般性原理见 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0ff7b4fb48fdf0eff.html">LV050-IAP跳转与向量表原理</a>。</p><h3 id="_3-复位路径的必然失效" tabindex="-1">3. 复位路径的必然失效 <a class="header-anchor" href="#_3-复位路径的必然失效" aria-label="Permalink to &quot;3. 复位路径的必然失效&quot;">​</a></h3><p>系统复位（软复位、看门狗复位、硬复位）后 <code>RCC-&gt;AHBENR</code> 的 <code>FSMCEN</code> 复位值为 0，FSMC 时钟被关断，外部 SRAM 立刻不可访问。由此得到两条推论：</p><p>（1）<strong>每次装载前必须重新 <code>FSMC_Init</code>，禁止&quot;检测到已初始化就跳过&quot;的优化</strong>——寄存器值可能还在，但时钟一定没了；</p><p>（2）<code>reboot</code> 命令（<code>NVIC_SystemReset()</code>，见 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0f2ee140ae99e895652.html">LV025-reboot命令实例</a>）回 Bootloader 的路径是安全的：复位后 PC 回到 <code>0x08000000</code>，Bootloader 反正每次都会重新初始化 FSMC 再装载。看门狗复位同理，见 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0f9ac42fecec3931c.html">LV055-看门狗问题与解决方案</a>。</p><h3 id="_4-时钟一致性约束" tabindex="-1">4. 时钟一致性约束 <a class="header-anchor" href="#_4-时钟一致性约束" aria-label="Permalink to &quot;4. 时钟一致性约束&quot;">​</a></h3><p>FSMC 的 <code>FSMC_BTRx</code> 时序参数（ADDSET、DATAST）是按<strong>特定 HCLK</strong> 配置的。如果 Bootloader 按 72MHz 配时序、APP 的 <code>SystemInit</code> 却把时钟改了，外部 SRAM 访问就违时序——症状是运行中随机 HardFault 或数据错乱，极难定位。所以工程约定是：<strong>Bootloader 与 APP 的时钟配置保持完全一致，APP 不改系统时钟</strong>。这条约定保护的也不止 FSMC：Bootloader 移交的其他外设配置同样依赖时钟不变。</p><h3 id="_5-契约清单汇总" tabindex="-1">5. 契约清单汇总 <a class="header-anchor" href="#_5-契约清单汇总" aria-label="Permalink to &quot;5. 契约清单汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th>契约</th><th>责任方</th><th>违反后果</th></tr></thead><tbody><tr><td>装载前完成 <code>FSMC_Init</code>（每次必做）</td><td>Bootloader</td><td>写入或取指直接 HardFault</td></tr><tr><td>时钟配置两边完全一致</td><td>双方</td><td>FSMC 时序静默错配，随机跑飞</td></tr><tr><td>APP 不改 FSMC 时序参数</td><td>APP</td><td>取指变垃圾数据，立即 HardFault</td></tr><tr><td>APP 不复用 FSMC 引脚做 GPIO</td><td>APP</td><td>总线信号被破坏</td></tr><tr><td>APP 不关 <code>RCC-&gt;AHBENR.FSMCEN</code></td><td>APP</td><td>外存瞬间不可访问</td></tr><tr><td>APP 不进改频类低功耗模式</td><td>APP</td><td>时钟变化导致时序失配</td></tr></tbody></table><h2 id="四、-板级资源冲突与风险分析" tabindex="-1">四、 板级资源冲突与风险分析 <a class="header-anchor" href="#四、-板级资源冲突与风险分析" aria-label="Permalink to &quot;四、 板级资源冲突与风险分析&quot;">​</a></h2><p>方案能不能落地，最终取决于这块板的具体资源格局。按严重程度列出三个问题。</p><h3 id="_1-暂存区容量给-大-app-封了顶" tabindex="-1">1. 暂存区容量给&quot;大 APP&quot;封了顶 <a class="header-anchor" href="#_1-暂存区容量给-大-app-封了顶" aria-label="Permalink to &quot;1. 暂存区容量给&quot;大 APP&quot;封了顶&quot;">​</a></h3><p>镜像必须先进暂存区再搬运——这是&quot;掉电后重发一条 <code>go</code> 就能复活&quot;收益的前提，而暂存区只有 256KB（<code>0x08040000</code> ~ <code>0x08080000</code>，分区见 <a href="/scm-docs/sdoc/online-upgrade/iap/126b0fcbd40c60cd0540e.html">LV030-FLASH-APP设计</a>）。外部 SRAM 容器虽然接近 1MB，<strong>APP 实际上限仍是 256KB</strong>——&quot;解除 24KB 限制&quot;的核心收益被 Flash 分区卡住了。想突破只有两条路：重分区（压缩 Bootloader 或砍掉 flash-app），或者跳过暂存直接流入外部 SRAM——后者会丢掉暂存收益，方案就变味了。</p><h3 id="_2-外部-sram-在这块板上不空" tabindex="-1">2. 外部 SRAM 在这块板上不空 <a class="header-anchor" href="#_2-外部-sram-在这块板上不空" aria-label="Permalink to &quot;2. 外部 SRAM 在这块板上不空&quot;">​</a></h3><p><a href="/scm-docs/sdoc/advanced-chapter/ethernet/126d628e13a516684ed019b4.html">LV001-以太网与DM9000硬件接口</a> 已经确认：IAP 现在就把 128KB 网络载荷缓冲放在外部 SRAM，访问互斥还要靠临界区保护；LV015 的示例还用 <code>__attribute__((at(0x68000000)))</code> 把数组钉在这个地址。代码容器一旦从 <code>0x68000000</code> 开始铺，这些缓冲全部要挪——外部 SRAM 必须重新分区（代码容器在前、缓冲区在后），链接脚本和所有 <code>at()</code> 地址同步修改。这还是&quot;多处同步&quot;的坑，只是同步点更多。</p><h3 id="_3-总线竞争被-取指-放大数倍" tabindex="-1">3. 总线竞争被&quot;取指&quot;放大数倍 <a class="header-anchor" href="#_3-总线竞争被-取指-放大数倍" aria-label="Permalink to &quot;3. 总线竞争被&quot;取指&quot;放大数倍&quot;">​</a></h3><p>现在的设计里只有数据面（缓冲读写、网卡收发）碰 FSMC，代码在 Flash 走 ICode 总线。APP 挪到外部 SRAM 之后：</p><p>（1）ICode 总线闲置，<strong>每条取指、每次中断向量表查询都挤上 System 总线</strong>，与内部 SRAM 数据、外设、FSMC 缓冲访问互相竞争；</p><p>（2）DM9000（NE2）与 IS62WV51216（NE3）共享 NOE/NWE/A7 信号线，FSMC 控制器在两片之间串行化；</p><p>（3）FSMC 异步时序加 16 位数据线，意味着一次 32 位取指要两次 FSMC 访问，粗估计算密集代码慢 4 ~ 10 倍，中断入口延迟明显增加。</p><p><strong>这个数字必须实测</strong>（用 DWT 周期计数器做基准），中断密集的场合很可能不可接受。这也是本节三个问题里唯一可能直接否决方案的。</p><h2 id="五、-结论与路线建议" tabindex="-1">五、 结论与路线建议 <a class="header-anchor" href="#五、-结论与路线建议" aria-label="Permalink to &quot;五、 结论与路线建议&quot;">​</a></h2><h3 id="_1-三条路线对比" tabindex="-1">1. 三条路线对比 <a class="header-anchor" href="#_1-三条路线对比" aria-label="Permalink to &quot;1. 三条路线对比&quot;">​</a></h3><table tabindex="0"><thead><tr><th>路线</th><th>适用场景</th><th>代价</th></tr></thead><tbody><tr><td>Flash 重分区，改用大容量 flash-app</td><td>目标只是解除 24KB 限制</td><td>需要重排 Flash 布局；执行速度不变、零 FSMC 依赖、契约最简，<strong>首选</strong></td></tr><tr><td>外部 SRAM 方案（本文）</td><td>需要运行期反复装载、Flash 擦写敏感</td><td>四节的三个问题全部要处理，性能实测过关才可上线</td></tr><tr><td>混合：热代码放内部 SRAM，冷代码放外部 SRAM</td><td>坚持外部 SRAM 且有实时性要求</td><td>链接脚本复杂度上升，中断处理函数需单独归段</td></tr></tbody></table><h3 id="_2-结论" tabindex="-1">2. 结论 <a class="header-anchor" href="#_2-结论" aria-label="Permalink to &quot;2. 结论&quot;">​</a></h3><p>外部 SRAM-APP 在机制上完全成立：取指区域合法、跳转流程同构、启动契约可落实。但放到这块板上，它解决的是代码体积问题，而这个问题用 Flash 重分区解决得更便宜、更快、更稳；外部 SRAM 方案的真正代价——暂存区封顶、缓冲区迁移、总线竞争——恰好落在这块板最拥挤的资源上。</p><p>给后续实施的两条建议：</p><p>（1）先做 DWT 性能实测：同一段业务代码分别在 Flash、内部 SRAM、外部 SRAM 运行，测指令吞吐与中断延迟，数据过关再谈采用；</p><p>（2）若采用，把 三、5 的契约清单原样写进 Bootloader 与 APP 的设计文档，每条契约都配上&quot;违反后会看到什么现象&quot;的描述，方便日后排查。</p><hr><p><em>本文档由 markdowncli 技能辅助生成</em></p>',73)])])}const u=d(s,[["render",l]]);export{S as __pageData,u as default};
